sys_script_include.script:
var FeedbackUtils = Class.create();
FeedbackUtils.prototype = {
    initialize: function() {
    },

    getFeedbackById: function(feedbackId) {
        var gr = new GlideRecord('Feedback'); 
        if (gr.get(feedbackId)) {
            return gr;
        }
        return null;
    },


    isFeedbackPositive: function(feedbackId) {
        var feedback = this.getFeedbackById(feedbackId);
        if (feedback && feedback.rating) {
            return feedback.rating == 'Good'; 
        }
        return false;
    },


    getFeedbackByEventId: function(eventId) {
        var feedbacks = [];
        var gr = new GlideRecord('Feedback'); 
        gr.addQuery('u_event_id', eventId);
        gr.query();
        while (gr.next()) {
            feedbacks.push(gr);
        }
        return feedbacks;
    },


    type: 'FeedbackUtils'
};
